{"cards": [{"node_code": "N_aeac6827952cd0d6", "definition": "研究去除基体表面油污、氧化皮、锈蚀及化学杂质的工艺，以及通过化学或电化学手段提高表面能、促进后续涂层结合的活化技术。", "boundary": "聚焦于表面污染物的去除及表面化学状态的初步调整。包括溶剂清洗、碱性脱脂、酸洗除锈、钝化处理及表面活化剂的使用。不涉及通过机械力改变表面形貌（如喷砂）或高能束改性，也不涉及涂层沉积过程。", "includes": ["溶剂、碱性或酸性清洗工艺及除油除锈技术", "表面钝化、磷化及化学活化处理", "表面能测试及清洁度评价标准"], "excludes": ["机械喷砂、抛光等改变表面形貌的工艺（归入机械、化学与等离子预处理）", "离子注入、激光清洗等高能束表面改性（归入表面改性与纹理化）"], "sibling_distinctions": [{"other_code": "N_19de069d9b0b97d0", "rule": "本节点侧重化学/电化学手段去除污染物及改变表面化学性质，兄弟节点侧重机械力或等离子物理手段改变表面形貌或微观结构；涉及酸洗归本节点，涉及喷砂归兄弟节点。"}], "cross_boundary_rule": "涉及表面去氧化层时，若通过酸洗或化学溶解归本节点；若通过喷砂或等离子轰击归兄弟节点。"}, {"node_code": "N_19de069d9b0b97d0", "definition": "研究利用机械力、化学蚀刻或等离子体轰击等手段改变基体表面形貌、粗糙度及微观结构，以增强涂层结合力的预处理技术。", "boundary": "聚焦于通过物理或化学机械作用改变表面几何特征及微观组织。包括喷砂、抛光、研磨、化学蚀刻及等离子清洗/活化。强调表面粗糙度、锚固效应及表面活性的物理/化学机械调控。不涉及单纯的化学清洗除油或涂层沉积。", "includes": ["喷砂、抛光、研磨等机械表面处理工艺", "化学蚀刻及等离子清洗、活化技术", "表面粗糙度、微观形貌及锚固效应分析"], "excludes": ["单纯的溶剂清洗或酸洗除油（归入清洗、除锈与活化）", "离子注入、激光改性等改变表层相组成或深度的高能束改性（归入表面改性与纹理化）"], "sibling_distinctions": [{"other_code": "N_aeac6827952cd0d6", "rule": "本节点侧重机械/物理手段改变表面形貌及微观结构，兄弟节点侧重化学手段去除污染物；涉及喷砂归本节点，涉及酸洗归兄弟节点。"}, {"other_code": "N_ad6d011d54bad883", "rule": "本节点侧重预处理工艺本身及其对表面形貌的影响，兄弟节点侧重预处理后界面结合机理及缺陷分析；涉及喷砂工艺参数归本节点，涉及喷砂后界面结合强度归兄弟节点。"}], "cross_boundary_rule": "涉及表面粗糙度控制时，若为增加机械锚固力的预处理归本节点；若为功能性微纳纹理制造归表面改性与纹理化节点。"}, {"node_code": "N_ad6d011d54bad883", "definition": "研究涂层与基体间界面结合机理、界面残余应力分布规律，以及孔隙、裂纹、剥离等界面缺陷的成因分析与控制方法。", "boundary": "聚焦于界面微观状态及力学行为。包括机械结合、化学结合、冶金结合等机理研究，界面热应力、残余应力测量与调控，以及界面缺陷（如孔隙、裂纹、分层）的表征与抑制。不涉及预处理具体工艺操作或涂层宏观性能测试。", "includes": ["界面结合机理（机械、化学、冶金）研究", "界面残余应力测量、分布及调控技术", "界面孔隙、裂纹、剥离等缺陷的表征与控制"], "excludes": ["表面清洗、喷砂等具体预处理工艺操作（归入清洗、除锈与活化或机械、化学与等离子预处理）", "涂层整体硬度、耐磨性等宏观性能测试（归入表面层评价与服役性能）"], "sibling_distinctions": [{"other_code": "N_aeac6827952cd0d6", "rule": "本节点侧重界面结合机理及缺陷分析，兄弟节点侧重去除污染物的具体工艺；涉及界面结合强度归本节点，涉及除油工艺归兄弟节点。"}, {"other_code": "N_19de069d9b0b97d0", "rule": "本节点侧重界面力学行为及缺陷控制，兄弟节点侧重改变表面形貌的预处理工艺；涉及界面残余应力归本节点，涉及喷砂工艺参数归兄弟节点。"}], "cross_boundary_rule": "涉及界面缺陷时，若侧重缺陷成因机理及控制策略归本节点；若侧重缺陷检测技术归表面层评价节点。"}]}
